import type { Metadata } from 'next';

export const metadata: Metadata = {
  title: 'Ley Orgánica | Tribunal de Cuentas de Río Negro',
};

export default function LeyOrganicaPage() {
  return (
    <section className="fade-in my-5 px-custom row legal-page">
      <div className="col-12 text-center">
        <div className="col-12">
          <h3 className="h4 mb-5" style={{ color: '#34373E' }}>LEY ORGÁNICA</h3>
        </div>
      </div>
      <div className="col-12">
        <p className="subtitle">LEY K Nº 2747</p>
        <p className="mb-4 subtitle">LEY ORGÁNICA DEL TRIBUNAL DE CUENTAS DE LA PROVINCIA DE RÍO NEGRO</p>

        <p className="subtitle"><strong>Capítulo I</strong></p>
        <p className="mb-4 subtitle"><strong>ORGANIZACIÓN</strong></p>

        <p className="mb-4"><strong>Artículo 1º - Artículos de la Constitución reglamentados.</strong> La presente Orgánica del Tribunal de Cuentas de la Provincia de Río Negro, reglamenta los artículos 161, 162, 163, 166 y 169 de la Constitución Provincial.</p>

        <p className="mb-4"><strong>Artículo 2º - Designación, autoridades, representación, remoción.</strong> El Tribunal de Cuentas está integrado por tres (3) miembros, designados y removidos en la forma establecida en el artículo 166 de la Constitución Provincial. Sus miembros no pueden, en su totalidad, pertenecer a la misma profesión universitaria exigida por el artículo 162 de la Constitución. La Presidencia del Tribunal es ejercida anualmente por el Vocal que el mismo cuerpo designe en la primera quincena de diciembre de cada año. El Presidente puede ser reelecto. Ejerce la representación del Tribunal y tiene la conducción administrativa, con las atribuciones y deberes que, legal y reglamentariamente, le correspondan.</p>

        <p className="mb-4"><strong>Artículo 3º - Requisitos, remuneración.</strong> Para ser miembro del Tribunal de Cuentas se requieren las mismas exigencias que para ser Legislador, teniendo sus mismas inmunidades, incompatibilidades, inhabilidades y las prohibiciones que impone el artículo 201 de la Constitución para magistrados y funcionarios del Poder Judicial, poseer título de abogado o graduado en ciencias económicas, debiendo acreditar una antigüedad de diez (10) años en el ejercicio profesional. Su remuneración es equivalente a la del Legislador.</p>

        <p className="mb-4"><strong>Artículo 4º - Juramento.</strong> Los miembros del Tribunal de Cuentas deben prestar juramento ante la Legislatura, de desempeñar fiel y legalmente sus funciones de acuerdo con la Constitución y las leyes de la provincia.</p>

        <p className="mb-4"><strong>Artículo 5º - Funcionamiento -Quórum-.</strong> El Tribunal debidamente integrado, emite sus resoluciones previa deliberación de sus miembros, con el voto coincidente de dos (2) de sus integrantes, siguiendo el orden con que han sido sorteados. Si no existe coincidencia entre los primeros, emite su voto superando el desacuerdo el Presidente del Tribunal, caso contrario la emisión de su voto es facultativa. El acuerdo y las resoluciones se dictan por mayoría y pueden ser redactados en forma impersonal.</p>

        <p className="mb-4"><strong>Artículo 6º - Recusación, excusación.</strong> Los Vocales del Tribunal y sus colaboradores sólo pueden ser recusados con causa. En estas cuestiones son de aplicación las disposiciones correspondientes del Código Procesal Civil y Comercial de la Provincia, dispuestas para los jueces de Tribunales Colegiados y son resueltas por el Tribunal debidamente integrado. Las resoluciones que se refieran a miembros del Tribunal, son recurribles ante el Superior Tribunal de Justicia.</p>

        <p className="mb-4"><strong>Artículo 7º - Subrogación del Presidente.</strong> En oportunidad del acuerdo anual de designación del Presidente, también se fija el orden en que los restantes miembros lo reemplazan en caso de ausencia u otro impedimento.</p>

        <p className="mb-4">
          <strong>Artículo 8º - Orden de subrogancia.</strong> En caso de recusación, excusación, licencia, vacaciones u otros impedimentos, el orden de los reemplazados es el siguiente:
          <br /><strong>a)</strong> De los Vocales del Tribunal:
          <br /><strong>1)</strong> Por el Fiscal de Investigaciones Administrativas.
          <br /><strong>2)</strong> Por un profesional designado por sorteo de una lista especial confeccionada por la Legislatura, en su sesión preparatoria anual, integrada por abogados y graduados en ciencias económicas que deben reunir las mismas condiciones que se requieran para integrar el Tribunal.
          <br /><strong>b)</strong> De los Secretarios:
          <br /><strong>1)</strong> Por los miembros del cuerpo técnico en orden de antigüedad.
          <br /><strong>2)</strong> Por abogado o graduado en ciencias económicas, que para cada caso en particular designe el Tribunal. En todos los supuestos de integración del Tribunal se debe tener en cuenta lo dispuesto respecto de su composición.
        </p>

        <p className="mb-4"><strong>Artículo 9º - Colaboradores, personal.</strong> Es asistido por un Secretario Auditor Legal y un Secretario Auditor Contable. También cuenta con un cuerpo técnico formado por contadores y abogados auditores y el personal que le asigne la Ley de Presupuesto. Para ser designado Secretario Auditor Legal o Abogado Auditor, es necesario poseer título de abogado con una antigüedad en el ejercicio de la profesión no menor de cinco (5) años. Para ser designado Secretario Auditor Contable o Contador Auditor, es necesario poseer título de Contador Público con una antigüedad en el ejercicio profesional de cinco (5) años. El cuerpo técnico también puede contar con otros profesionales según se establece en la Ley de Presupuesto.</p>

        <p className="mb-4"><strong>Artículo 10 - Designación. Remoción.</strong> Los Secretarios son designados y removidos por el Tribunal. Los contadores y abogados auditores y demás personal de planta, son designados por el Tribunal siguiendo el procedimiento del concurso público y tienen estabilidad en los términos que determine el estatuto respectivo.</p>

        <p className="subtitle"><strong>Capítulo II</strong></p>
        <p className="mb-4 subtitle"><strong>FUNCIONES</strong></p>

        <p className="mb-4">
          <strong>Artículo 11 - Funciones.</strong> Como órgano de control externo del Estado, son funciones del Tribunal de Cuentas:
          <br /><strong>a)</strong> Control de legitimidad. Controlar la legitimidad de lo ingresado e invertido en función del presupuesto por la administración centralizada y descentralizada, empresas del Estado, sociedades con participación estatal mayoritaria y beneficiarios de aportes provinciales.
          <br /><strong>b)</strong> Fiscalización y vigilancia. Fiscalizar y vigilar el cumplimiento de las disposiciones legales y procedimientos administrativos.
          <br /><strong>c)</strong> Examen y juicio de cuentas. Realizar el examen y juicio de cuentas de los responsables.
          <br /><strong>d)</strong> Juicio de responsabilidad. Realizar el juicio administrativo de responsabilidad, formulando los cargos cuando corresponda.
          <br /><strong>e)</strong> Investigaciones. Promover las investigaciones que resulten necesarias, a través de la Fiscalía de Investigaciones Administrativas, con traslado de todos los datos y elementos con que se cuente.
          <br /><strong>f)</strong> Dictamen. Dictaminar sobre las cuentas de inversión del presupuesto que el Poder Ejecutivo presente a la Legislatura para su aprobación.
          <br /><strong>g)</strong> Interpretación legal. Interpretar las normas establecidas por la presente, en su ámbito de actuación.
          <br /><strong>h)</strong> Control municipal. Controlar los municipios cuando lo soliciten sus órganos competentes.
          <br /><strong>i)</strong> Informe anual. Presentar a la Legislatura el informe anual sobre los resultados del control que realiza de su gestión y emitir opinión sobre los procedimientos administrativos en uso, recomendando la reforma de los mismos con el objeto de prevenir irregularidades y mejorar la eficiencia del servicio administrativo del Estado.
          <br /><strong>j)</strong> Órganos de fiscalización. Proveer a la designación de los órganos de fiscalización interna y externa de las empresas, sociedades, entidades crediticias, entes y organismos del Estado.
        </p>

        <p className="subtitle"><strong>Capítulo III</strong></p>
        <p className="mb-4 subtitle"><strong>FACULTADES</strong></p>

        <p className="mb-4">
          <strong>Artículo 12 - Facultades.</strong> A los fines del cumplimiento de sus funciones, el Tribunal tiene las siguientes facultades:
          <br /><strong>a)</strong> De organización y administración.
          <br /><strong>1)</strong> Reglamento: Dictar su reglamento orgánico funcional con aprobación de la Legislatura y las instrucciones que juzgue necesarias para asegurar el cumplimiento de sus funciones.
          <br /><strong>2)</strong> Presupuesto: Elaborar y elevar su proyecto de presupuesto al Poder Legislativo para su consideración, dentro de los plazos que el titular de éste fije.
          <br /><strong>3)</strong> Gestión administrativa: Autorizar y aprobar sus gastos con arreglo a lo que establece el reglamento del Poder Legislativo, realizando el control externo de la gestión administrativa por parte de una Comisión Especial de la Legislatura, a la que debe efectuar sus rendiciones de cuentas, de acuerdo a lo que establece la legislación.
          <br /><strong>4)</strong> Personal: Designar y remover al personal de su dependencia, conforme a las disposiciones legales en vigencia.
          <br /><strong>b)</strong> De control.
          <br /><strong>1)</strong> Análisis: Analizar los actos administrativos que se refieran a la hacienda pública y observarlos cuando contraríen o violen disposiciones legales o reglamentarias, en cumplimiento de las facultades establecidas en el apartado 6) del presente.
          <br /><strong>2)</strong> Informes: Dirigirse a los poderes públicos nacionales, provinciales y municipales solicitando de las dependencias de la administración provincial y municipal, los informes, antecedentes y documentación que considere necesarios para el cumplimiento de sus funciones, siendo obligatorio para los organismos provinciales y municipales, dar respuesta a sus requerimientos, dentro de los plazos que fije y bajo apercibimiento de aplicar las sanciones previstas por la Ley.
          <br /><strong>3)</strong> Dictámenes: Solicitar directamente informes o dictámenes a la Fiscalía de Estado y a organismos técnicos de la Provincia.
          <br /><strong>4)</strong> Requerimientos: Requerir informes de la Contaduría de la Provincia, cuando lo estime necesario, sobre el desarrollo y registro de las operaciones financiero-patrimoniales.
          <br /><strong>5)</strong> Delegaciones: Organizar delegaciones, en las dependencias de los organismos del Estado, en la administración centralizada y descentralizada, dentro o fuera de la capital provincial.
          <br /><strong>6)</strong> Auditorías: Constituirse en los organismos del Estado, cualquiera sea su naturaleza jurídica, para efectuar inspecciones, auditorías, comprobaciones y verificaciones. Los responsables de los lugares que son objeto de inspección, tienen obligación de entregar la documentación que les es requerida y dar las explicaciones que se les soliciten en forma inmediata. En caso de negativa, previa formal intimación, citando este artículo, puede requerirse el auxilio de la fuerza pública para obtener lo solicitado. En el caso de los sujetos a control del artículo 17, incisos b) y c) puede requerir de la Justicia la autorización necesaria para realizar allanamientos e inclusive el auxilio de la fuerza pública.
          <br /><strong>7)</strong> Rendición de cuentas: Requerir con carácter conminatorio la rendición de cuentas y fijar plazos perentorios de presentación a los que, teniendo la obligación de hacerlos, fueran remisos o morosos.
          <br /><strong>8)</strong> Reglamentar las normas que fijan las condiciones a que deben ajustarse las rendiciones de cuentas.
          <br /><strong>9)</strong> Proponer y recomendar a la Legislatura el mejoramiento de la legislación para optimizar el funcionamiento de la administración.
          <br /><strong>c)</strong> De aplicación de multas. Multas, comunicaciones: Aplicar multas de hasta el 50% de la retribución mensual a:
          <br /><strong>1)</strong> Los responsables morosos de rendiciones de cuentas, una vez vencido el término de emplazamiento;
          <br /><strong>2)</strong> Los responsables de transgresiones legales o reglamentarias, aun cuando no han causado perjuicio a la hacienda pública;
          <br /><strong>3)</strong> Los que desobedecen sus resoluciones. También puede aplicar multas en los casos del artículo 62 de la presente, conforme la gravedad de la transgresión realizada. En todos los casos, la sanción aplicada es puesta en conocimiento del superior jerárquico del agente sancionado y no obsta los procedimientos del juicio de cuentas o de responsabilidad que pudieren corresponder.
        </p>

        <p className="mb-4"><strong>Artículo 13 - Observaciones, insistencia.</strong> En caso de producirse observaciones por parte del Tribunal de Cuentas, son comunicadas al titular del organismo, quedando suspendido el cumplimiento del acto en todo o en la parte observada, cuando corresponda, el titular del poder del cual depende el organismo, bajo su exclusiva responsabilidad, puede insistir en los actos observados. En tal caso el Tribunal de Cuentas comunica dentro del término de cinco (5) días a la Legislatura, tanto su observación como el acto de insistencia, acompañando copia de los antecedentes que fundamentaron la observación.</p>

        <p className="mb-4"><strong>Artículo 14 - Intervención en sumarios.</strong> Es obligación de los titulares de los organismos mencionados en el artículo 11, inciso a), poner en conocimiento del Tribunal en un plazo de cinco (5) días, el inicio de sumarios administrativos o actuación sumarial que se promueva por cualquier causa contra agentes de la administración, responsables de rendiciones de cuentas y/o que manejen valores y/o fondos y/o bienes, exclusivamente en salvaguarda de intereses fiscales que pueden estar afectados. En caso de omisión del aviso, el titular del organismo es responsable solidario por los perjuicios que sufra el Estado. El Tribunal da intervención a la Fiscalía de Investigaciones Administrativas para la sustanciación de los sumarios, conforme el artículo 7º inciso a) de la Ley Provincial K Nº 2394.</p>

        <p className="mb-4"><strong>Artículo 15 - Pronunciamiento previo.</strong> El pronunciamiento del Tribunal de Cuentas es previo a toda acción judicial tendiente a hacer efectiva la responsabilidad civil de los agentes de la administración pública sometidos a su jurisdicción conforme a esta Ley, dentro de la competencia específica del Tribunal de Cuentas. Sin embargo, si media condena judicial contra el Estado por hechos imputables a sus agentes, en los que la sentencia respectiva determine la responsabilidad civil de los mismos, es título suficiente para producir la resolución administrativa condenatoria y, en su caso, promover contra el responsable la acción que corresponda. Cuando se trata de eventuales delitos penales, la falta de pronunciamiento del Tribunal, no obsta a la radicación oportuna de la correspondiente denuncia.</p>

        <p className="mb-4"><strong>Artículo 16 - Comunicación de las denuncias recibidas.</strong> Debe poner en conocimiento de la Fiscalía de Investigaciones Administrativas la recepción de cualquier denuncia sobre la posible transgresión, por parte de funcionarios y agentes de los organismos mencionados en el artículo 11, inciso a), a las normas que rijan la gestión financiero-patrimonial, aunque de ella no se derive daño para la hacienda, a efectos de que se promuevan las investigaciones correspondientes cuando resulten necesarias.</p>

        <p className="subtitle"><strong>Capítulo IV</strong></p>
        <p className="mb-4 subtitle"><strong>SUJETOS DEL CONTROL</strong></p>

        <p className="mb-4">
          <strong>Artículo 17 - Sujetos a control.</strong> Están sujetos a la jurisdicción y competencia del Tribunal de Cuentas:
          <br /><strong>a)</strong> Todo funcionario o agente de los organismos descriptos en el artículo 11, inciso a), de la administración provincial.
          <br /><strong>b)</strong> Todos aquellos organismos, instituciones o personas, que sin ser agentes del Estado, manejen o tengan bajo su custodia bienes o fondos públicos. Esta responsabilidad se extiende, salvo que justifiquen que no medió negligencia de su parte, a la gestión de los créditos del Estado, por cualquier título que sea, a las rentas que deja de percibir, a las entregas indebidas de bienes a su cargo o custodia y a la pérdida o sustracción de los mismos.
          <br /><strong>c)</strong> Haciendas paraestatales: Las entidades de derecho privado en cuya dirección o administración tenga responsabilidad el Estado o a las cuales éste se haya asociado garantizando materialmente su solvencia o utilidad, o les hayan otorgado concesiones, privilegios, aportes o subsidios para su instalación o funcionamiento o con las cuales el Estado haya suscripto contratos condicionados, cuyo incumplimiento por parte de las entidades privadas, afecte la hacienda del Estado. En estos casos, las entidades mencionadas quedan comprendidas, a los efectos de la presente, en la denominación de haciendas paraestatales y sometidas a la jurisdicción del Tribunal de Cuentas, que puede fiscalizar y vigilar en todo o en parte y con alcance permanente, transitorio o eventual, su actividad económica.
        </p>

        <p className="subtitle"><strong>Capítulo V</strong></p>
        <p className="mb-4 subtitle"><strong>NORMAS ADMINISTRATIVAS</strong></p>

        <p className="mb-4"><strong>Artículo 18 - Responsabilidad solidaria.</strong> Los actos u omisiones violatorios de disposiciones legales o reglamentarias comportan responsabilidades solidarias para quienes lo dispongan, ejecuten o intervengan. Los agentes que reciban orden de hacer o no hacer, deben advertir por escrito a su respectivo superior sobre toda posible infracción que traiga aparejado el cumplimiento de dichas órdenes. De lo contrario, incurren en responsabilidad exclusiva si aquél no ha podido conocer la causa de la irregularidad, sino por su advertencia y observación.</p>

        <p className="mb-4"><strong>Artículo 19 - Cese de funciones.</strong> La denuncia, separación del cargo, incapacidad legalmente declarada o muerte del responsable no impide o paraliza el juicio de cuenta o responsabilidad patrimonial, pues el agente sólo queda eximido de su responsabilidad una vez aprobada la rendición de cuentas de su gestión. En los últimos casos, se sustancian las actuaciones con los curadores o herederos del causante.</p>

        <p className="mb-4"><strong>Artículo 20 - Ficta aprobación.</strong> La cuenta se considera aprobada cuando no se hayan formulado o notificado observaciones, reparos o cargos, dentro de los tres (3) años a contar desde que la misma esté sometida a verificación.</p>

        <p className="mb-4"><strong>Artículo 21 - Caducidad de la instancia.</strong> Se produce caducidad de la instancia cuando no se insta o prosigan los autos dentro del término de seis (6) meses de la contestación del traslado por el responsable.</p>

        <p className="mb-4"><strong>Artículo 22 - Improcedencia.</strong> No se produce caducidad de instancia en los procedimientos de ejecución de sentencia.</p>

        <p className="mb-4"><strong>Artículo 23 - Prescripción.</strong> La acción emergente de una cuenta prescribe a los cinco (5) años de elevación de la misma al Tribunal.</p>

        <p className="mb-4"><strong>Artículo 24 - Suspensión de la prescripción.</strong> Cuando la responsabilidad puede alcanzar a los miembros o funcionarios sujetos a procedimiento de juicio político o juzgamiento por el Consejo de la Magistratura, el Tribunal de Cuentas lo comunica a la Legislatura o al Consejo según corresponda, reservando las actuaciones, suspendiendo el término de la prescripción de la acción, hasta que se hayan resuelto en forma definitiva, las denuncias o pedidos de juicio político. Cuando los responsables hayan perdido sus fueros, cesado en sus cargos o mandatos, se reanuda el cómputo de los plazos fijados en la presente.</p>

        <p className="mb-4"><strong>Artículo 25 - Responsabilidad emergente.</strong> Determinada la situación prevista en los artículos precedentes, se transfiere la responsabilidad que puede existir a los funcionarios que son declarados culpables de la demora en la tramitación de los autos, su caducidad o prescripción de la cuenta.</p>

        <p className="subtitle"><strong>Capítulo VI</strong></p>
        <p className="mb-4 subtitle"><strong>NORMAS JURISDICCIONALES</strong></p>

        <p className="mb-4"><strong>Artículo 26 - Garantías.</strong> No pueden iniciarse procedimientos ni aplicarse sanciones a los responsables, sino por actos u omisiones que importen violación a normas legales o reglamentarias vigentes con anterioridad al hecho de la causa. Nadie puede ser sancionado en juicio ante el Tribunal de Cuentas, sino una sola vez por la misma infracción. Pueden aplicarse simultáneamente con la formulación de cargo, las multas previstas en el artículo 12, inciso c), de la presente. No puede aplicarse por analogía otra Ley que la que rige el caso, ni interpretarse ésta extensivamente en contra del enjuiciado. En caso de duda debe estar siempre a lo más favorable al enjuiciado.</p>

        <p className="mb-4"><strong>Artículo 27 - Pedidos de Informes y documentos. Medidas para mejor proveer.</strong> El Tribunal de Cuentas de oficio o a pedido del responsable, puede requerir en forma directa en los términos del artículo 12, inciso b), apartado 2), a las oficinas públicas de cualquier jurisdicción –que los posean o deban proporcionarlos–, los documentos o informes que se relacionen con los juicios sustanciados ante el Tribunal de Cuentas o con las rendiciones de cuentas, pudiendo inclusive ejercitar las facultades concedidas en el citado artículo 12, inciso b), apartado 6), en el cumplimiento de su función jurisdiccional.</p>

        <p className="mb-4"><strong>Artículo 28 - Obligación de denunciar irregularidades.</strong> Los agentes del Estado que tengan conocimiento de irregularidades que ocasionen o puedan originar perjuicio a la hacienda pública, deben comunicarla de inmediato al superior jerárquico, quien procede por la vía administrativa que corresponda, a poner en conocimiento del Tribunal de Cuentas mediante relación circunstanciada, la presunta irregularidad.</p>

        <p className="mb-4"><strong>Artículo 29 - Remisión al Código Procesal Penal.</strong> Los sumarios cuya instrucción ordenare el Tribunal de Cuentas, a los fines de la presente, deben regirse supletoriamente por el Código Procesal Penal de la Provincia, en cuanto es aplicable y asegurar la defensa en juicio del responsable.</p>

        <p className="mb-4"><strong>Artículo 30 - Domicilio de los responsables.</strong> El domicilio legal de los responsables por juicio ante el Tribunal de Cuentas, es el de la repartición del Estado a la que pertenecen o a través de la cual haya surgido su obligación de rendir cuentas o su responsabilidad. En caso de baja del agente responsable, todas las comunicaciones, notificaciones o citaciones, deben practicarse en el domicilio real del mismo. El domicilio legal de los agentes de haciendas paraestatales, es el de las entidades de derecho privado correspondiente.</p>

        <p className="mb-4"><strong>Artículo 31 - Domicilio desconocido.</strong> Cuando se ignora el domicilio del responsable o no sea posible lograr aviso de su notificación, la misma debe practicarse mediante edicto que se publica por tres (3) días en el Boletín Oficial y un diario de circulación regional.</p>

        <p className="subtitle"><strong>Capítulo VII</strong></p>
        <p className="mb-4 subtitle"><strong>DE LAS CUENTAS</strong></p>

        <p className="mb-4"><strong>Artículo 32 - Presentación.</strong> Los responsables de las distintas jurisdicciones en los poderes del Estado, obligados a rendir cuentas, deben presentar las rendiciones a los respectivos servicios administrativos que determine la Ley Provincial H Nº 3186, para su inclusión en la rendición universal que éstos elevan mensualmente al Tribunal de Cuentas o en los plazos fijados por la Ley.</p>

        <p className="mb-4"><strong>Artículo 33 - Formalidades de la rendición. Otros obligados a rendir cuentas.</strong> Las rendiciones deben ajustarse a las normas vigentes, reglamentaciones, modalidades e instrucciones que determine el Tribunal de Cuentas. Las rendiciones de cuentas de los responsables de dependencias que, por su naturaleza no se encuentren bajo la jurisdicción de algún servicio administrativo, son elevadas directamente al Tribunal de Cuentas. Los demás responsables definidos en el artículo 17, deben ajustar sus acciones a las disposiciones de la presente y de la Ley Provincial H Nº 3186, en cuanto le son aplicables y, en especial, a los plazos, instrucciones y formalidades que determine la reglamentación.</p>

        <p className="mb-4"><strong>Artículo 34 - Rendiciones del Tribunal de Cuentas.</strong> Las rendiciones de cuentas que formule el Tribunal de Cuentas, están sometidas a la jurisdicción de una Comisión Especial que designa la Legislatura, siendo de aplicación para su trámite las normas fijadas en la presente.</p>

        <p className="subtitle"><strong>Capítulo VIII</strong></p>
        <p className="mb-4 subtitle"><strong>JUICIO DE CUENTAS</strong></p>

        <p className="mb-4"><strong>Artículo 35 - Verificación.</strong> Presentado el expediente de rendición al Tribunal de Cuentas, se resuelve su estudio y no puede salir bajo ningún concepto hasta el fallo definitivo. Las rendiciones de cuentas son verificadas por el Tribunal de Cuentas en la forma que se establece en el reglamento orgánico en sus aspectos formales, legales, contables, numéricos y documentales. También puede disponer verificaciones in situ, para el examen integral, pruebas selectivas de la documentación u otros procedimientos, cuando lo considere conveniente.</p>

        <p className="mb-4"><strong>Artículo 36 - Fallo aprobatorio.</strong> La aprobación de la cuenta queda formalizada por resolución del Tribunal de Cuentas que así lo determine. Dispone, asimismo, las registraciones que debe realizar la Contaduría General, la comunicación al responsable, la publicación por un (1) día en el Boletín Oficial y el archivo de las actuaciones.</p>

        <p className="mb-4"><strong>Artículo 37 - Impugnaciones, observaciones o reparos.</strong> En los casos que una rendición sea objeto de observaciones, impugnaciones o reparos, debe darse vista al responsable por un término que no puede ser inferior a quince (15), ni mayor de treinta (30) días, contados desde la fecha de su notificación. El Tribunal de Cuentas puede ampliar este plazo cuando la naturaleza del asunto o razón de distancia lo justifique.</p>

        <p className="mb-4"><strong>Artículo 38 - Comparencia.</strong> Toda persona afectada por observaciones, reparos o cargos en un juicio de cuentas, puede comparecer por sí, por apoderado o por escrito a contestarlo, ofreciendo en el primer escrito la prueba que hace valer.</p>

        <p className="mb-4"><strong>Artículo 39 - Prueba.</strong> El Tribunal, de oficio o a pedido del responsable, dicta resolución abriendo el procedimiento a prueba por el término de veinte (20) días. El responsable acompaña, en su primer escrito, los documentos que hagan a su descargo y solicita al Tribunal que requiera los que deban obrar en oficinas públicas. También se solicita, cuando corresponda, de las oficinas públicas de cualquier jurisdicción que posean o deban proporcionarlos los documentos, informes, copias y certificaciones que se relacionen con el reparo o impugnación u observación. Asimismo el Tribunal, a pedido del responsable, puede fijar un término extraordinario por igual lapso, cuando la naturaleza de las actuaciones o la complejidad del asunto lo justifiquen.</p>

        <p className="mb-4"><strong>Artículo 40 - Término.</strong> En la producción de prueba ordenada, todos los funcionarios provinciales o municipales, están obligados a suministrar al Tribunal dentro de los términos fijados, la prueba a producir. En los oficios o mandamientos, el Tribunal debe expresar el término y su vencimiento conforme al artículo 39. Asimismo debe transcribirse en el respectivo instrumento la sanción prevista en el artículo 12 inciso c), para el caso de incumplimiento o mora de lo solicitado.</p>

        <p className="mb-4">
          <strong>Artículo 41 - Conclusión, tramitación y fallo.</strong> Concluida la tramitación, el Tribunal de Cuentas dicta la resolución que corresponda:
          <br /><strong>a)</strong> Interlocutoria: Cuando para mejor proveer tenga que ordenar alguna diligencia;
          <br /><strong>b)</strong> Definitiva: Practicadas que son dichas diligencias o cuando ellas no son necesarias, aprobando la cuenta y declarando libre al responsable o bien determinando las partidas ilegítimas no aceptadas o no comprobadas y ordenando se proceda a la cobranza, con los alcances que, en tal virtud, se declare a favor del fisco, con más los intereses y recargos que correspondan, calculados desde la fecha de entrega de los fondos al responsable. La resolución interlocutoria no impide al Tribunal de Cuentas el descargo parcial de las operaciones que éste no considere objetables.
        </p>

        <p className="mb-4"><strong>Artículo 42 – Resolución.</strong> Cuando la resolución definitiva sea absolutoria, se procede conforme al artículo 36. Si la resolución es condenatoria, se procede conforme a lo establecido en el Capítulo XIV. Si durante la sustanciación del juicio de cuentas se presume que se ha cometido algún delito, el Tribunal formula la correspondiente denuncia ante la justicia competente por intermedio de la Fiscalía de Investigaciones Administrativas, notificando de lo actuado a la Fiscalía de Estado. En todos los casos se continúa el trámite sin perjuicio de la aplicación de la multa, si corresponde, en virtud de lo dispuesto en el artículo 12, inciso c).</p>

        <p className="subtitle"><strong>Capítulo IX</strong></p>
        <p className="mb-4 subtitle"><strong>JUICIOS DE RESPONSABILIDAD</strong></p>

        <p className="mb-4"><strong>Artículo 43 - Naturaleza.</strong> El juicio administrativo de responsabilidad tiene por objeto determinar el daño causado por la conducta dolosa, culposa o negligente del agente en gestión, respecto de los bienes del Estado y la determinación de los responsables.</p>

        <p className="mb-4">
          <strong>Artículo 44 - Forma de iniciación.</strong> La determinación administrativa de responsabilidad, que no es emergente de una rendición de cuentas, se hace mediante juicio que sustancia el Tribunal de Cuentas. Se inicia:
          <br /><strong>a)</strong> Por denuncia: De acuerdo a lo establecido en el artículo 28.
          <br /><strong>b)</strong> De oficio: Cuando el Tribunal presuma que por actos, hechos u omisiones, se pueda causar perjuicio a la hacienda pública.
          <br /><strong>c)</strong> Por la Fiscalía de Investigaciones Administrativas: De acuerdo a su Ley Orgánica.
        </p>

        <p className="mb-4"><strong>Artículo 45 - Del trámite previo a la determinación de responsabilidad. Procedimiento.</strong> Se establece como previo al juicio de responsabilidad, un procedimiento sumario de investigación, sustanciado a través de la Fiscalía de Investigaciones Administrativas a los fines de determinar, prima facie, la existencia de un perjuicio real para la hacienda pública y/o, en su caso, la transgresión de normas legales o procedimientos que regulen la administración y disposición de los bienes del Estado y el o los presuntos responsables.</p>

        <p className="mb-4"><strong>Artículo 46 - Sumario. Medidas precautorias.</strong> Una vez dictado el auto de iniciación, el sumario es remitido a la Fiscalía de Investigaciones Administrativas para su instrucción, con todos los antecedentes de la causa. El Tribunal o la Fiscalía de Investigaciones Administrativas, también pueden solicitar a la Justicia Ordinaria, medidas precautorias en los bienes de los supuestos responsables para resguardo del interés de la hacienda pública.</p>

        <p className="mb-4"><strong>Artículo 47 - Término.</strong> El sumario debe sustanciarse en un plazo ordinario que no puede exceder de sesenta (60) días, pudiendo el Tribunal prorrogarlo, mediante resolución fundada, a solicitud de la Fiscalía de Investigaciones Administrativas.</p>

        <p className="mb-4"><strong>Artículo 48 - Clausura y elevación.</strong> Vencido el término previsto en el artículo anterior y antes de su vencimiento si se encontrara agotado, la Fiscalía de Investigaciones Administrativas, declara cerrado el sumario y con su dictamen eleva las actuaciones al Tribunal, dentro de los diez (10) días hábiles siguientes.</p>

        <p className="mb-4">
          <strong>Artículo 49 -</strong> El Fiscal de Investigaciones Administrativas, mediante dictamen fundado que debe contener los datos personales del o los responsables, una relación clara, precisa y circunstanciada de los hechos y las normas legales aplicables, puede:
          <br /><strong>a)</strong> Disponer el archivo del expediente si del análisis del mismo resulta la inexistencia de transgresión a norma legal o reglamentaria alguna y/o inexistencia de daños o perjuicios para la hacienda pública y/o falta de responsabilidad del autor o autores.
          <br /><strong>b)</strong> Disponer la iniciación de juicio de responsabilidad, debiendo, en este caso, ofrecer la prueba que no se ha producido en la etapa de investigación.
          <br /><strong>c)</strong> Solicitar la aplicación del artículo 12, inciso c) de la presente. La Fiscalía de Investigaciones Administrativas es parte en el juicio administrativo de responsabilidad correspondiente.
        </p>

        <p className="mb-4"><strong>Artículo 50 - Iniciación, comparencia y traslado.</strong> El juicio comienza con la citación de los presuntos responsables, para que comparezcan a tomar intervención en el juicio y en dicho acto de comparencia se le corre traslado con copia del cargo y/o reparo que se haya formulado, para que dentro del término de quince (15) días lo conteste por sí o por intermedio de apoderado. En el escrito de contestación, el presunto responsable ofrece la prueba de que intenta valerse, acompañando la documental que obrare en su poder o indicando el lugar donde se encuentra.</p>

        <p className="mb-4"><strong>Artículo 51 - Prueba, admisión y rechazo.</strong> El Tribunal ordena la recepción oportuna de las pruebas ofrecidas, pudiendo rechazar, por auto fundado, la manifiestamente improcedente o superabundante. Si no se ofrece la prueba o el Tribunal lo considera insuficiente, de oficio puede disponer la producción de la pertinente y útil, a tales efectos.</p>

        <p className="mb-4"><strong>Artículo 52 - Plazo.</strong> En el mismo proveído fija el plazo de prueba que no puede ser inferior a treinta (30) días. En los supuestos que no se ofrecen pruebas y que el Tribunal no dispone de oficio su producción, se confiere traslado a las partes por su orden por el plazo de seis (6) días, quedando la causa en estado para dictar sentencia.</p>

        <p className="mb-4"><strong>Artículo 53 - Desistimiento.</strong> En todos los casos el Tribunal por auto, puede tener a las partes como desistidas de la prueba cuando no hayan instado convenientemente la misma. Sin embargo el Tribunal puede dentro del plazo fijado, instar la producción de la prueba que considere de interés.</p>

        <p className="mb-4"><strong>Artículo 54 - De la conclusión.</strong> Vencido el término de prueba, el Tribunal ordena su clausura. Si se ha producido prueba, el Presidente confiere traslado a las partes por su orden y por el plazo de seis (6) días a cada uno para que, si lo creen conveniente, aleguen sobre el mérito de la misma.</p>

        <p className="mb-4"><strong>Artículo 55 - Autos a sentencia.</strong> Producidos los alegatos, o transcurridos los plazos para ello, el Presidente dicta la providencia de autos a sentencia.</p>

        <p className="mb-4"><strong>Artículo 56 - Medidas de mejor proveer.</strong> Desde el llamamiento de autos queda cerrada la discusión y no pueden presentarse más escritos ni producirse más pruebas. Sin embargo, el Tribunal, previo a la sentencia, puede dictar interlocutoria, cuando para mejor proveer tenga que ordenar alguna diligencia. Tal medida debe sustanciarse en el término de diez (10) días.</p>

        <p className="mb-4"><strong>Artículo 57 - Sentencia definitiva.</strong> El Tribunal pronuncia sentencia definitiva, absolutoria o condenatoria, en un término no mayor de treinta (30) días, de encontrarse el expediente para resolver.</p>

        <p className="mb-4"><strong>Artículo 58 - Absolutoria.</strong> Si es sentencia absolutoria, es fundada y expresa, llevando aparejada la providencia de archivo de las actuaciones, previa notificación.</p>

        <p className="mb-4"><strong>Artículo 59 - Condenatoria.</strong> La sentencia condenatoria es fundada y expresa. Debe fijar la suma a ingresar por el responsable cuyo pago se le intima con fijación de término, formulando y mandando a registrar el cargo correspondiente.</p>

        <p className="mb-4"><strong>Artículo 60 - Efectos de la sentencia.</strong> La sentencia firme del Tribunal de Cuentas agota la etapa administrativa, pudiendo interponer contra aquélla recurso de apelación ordinaria, por ante el Superior Tribunal de Justicia de la Provincia, en los términos del artículo 14 de las Normas Complementarias de la Constitución Provincial y conforme las normas procesales de aplicación.</p>

        <p className="subtitle"><strong>Capítulo X</strong></p>
        <p className="mb-4 subtitle"><strong>CONSECUENCIA Y ALCANCES DEL JUICIO DE RESPONSABILIDAD</strong></p>

        <p className="mb-4"><strong>Artículo 61 - Inexistencia de daño.</strong> Cuando en el juicio de responsabilidad no se acreditan daños para la hacienda pública, pero sí procedimientos administrativos irregulares, el Tribunal de Cuentas puede imponer al responsable multa, conforme a la facultad que le confiere el artículo 12, inciso c), de la presente.</p>

        <p className="mb-4"><strong>Artículo 62 - Sanción de la administración.</strong> Las disposiciones del presente Capítulo, no excluyen las medidas de carácter disciplinario que se adopten conforme los respectivos regímenes jurídicos, los que son independientes del juicio y no influyen en la decisión de éste.</p>

        <p className="mb-4"><strong>Artículo 63 - Responsabilidad penal.</strong> Si durante la sustanciación del juicio de responsabilidad se presume que se ha cometido algún delito, el Tribunal formula la correspondiente denuncia ante la Justicia competente, por intermedio de la Fiscalía de Investigaciones Administrativas, notificando de lo actuado a la Fiscalía de Estado.</p>

        <p className="subtitle"><strong>Capítulo XI</strong></p>
        <p className="mb-4 subtitle"><strong>DISPOSICIONES COMUNES A LOS CAPÍTULOS VII, IX Y X – LA REBELDÍA</strong></p>

        <p className="mb-4"><strong>Artículo 64 - Notificaciones y citaciones.</strong> Los emplazamientos, notificaciones de providencias, resoluciones y fallos, se realizan en forma personal por cédula u oficio bajo pena de nulidad. Las simples providencias o resoluciones que no causen estado, por nota.</p>

        <p className="mb-4"><strong>Artículo 65 - Costas.</strong> En todos los casos los gastos, costas y honorarios devengados durante los juicios de cuentas y de responsabilidad, son por el orden causado, cualquiera fuera el resultado y el carácter del fallo.</p>

        <p className="mb-4"><strong>Artículo 66 - Declaración de rebeldía.</strong> El o los responsables, debidamente citados, que no comparecen o abandonan el juicio después de haber comparecido, son declarados en rebeldía por el Tribunal.</p>

        <p className="mb-4"><strong>Artículo 67 - Notificación.</strong> La resolución de rebeldía se notifica por cédula o, en su caso, por edictos durante tres (3) días en el Boletín Oficial. Las sucesivas resoluciones se tienen por notificadas por ministerio de ley.</p>

        <p className="mb-4"><strong>Artículo 68 - Efectos.</strong> La rebeldía no altera la secuela regular del juicio. La sentencia, en su momento, es pronunciada según el mérito de la causa y conforme a las constancias de autos.</p>

        <p className="mb-4"><strong>Artículo 69 - Notificación de la sentencia.</strong> La sentencia se hace saber en la forma prescripta por el artículo 31 de la presente.</p>

        <p className="mb-4"><strong>Artículo 70 - Comparencia del rebelde.</strong> Si el rebelde comparece en cualquier estado del juicio, es admitido como parte, prosiguiendo la causa con su intervención, en el estado en que se encuentre, sin que la misma pueda en ningún caso retrogradarla.</p>

        <p className="subtitle"><strong>Capítulo XII</strong></p>
        <p className="mb-4 subtitle"><strong>LOS RECURSOS EN EL PROCEDIMIENTO</strong></p>

        <p className="mb-4"><strong>Artículo 71 - Reglas generales.</strong> Las resoluciones del Tribunal de Cuentas dictadas conforme a los procedimientos establecidos en los capítulos VII y IX de la presente, son recurribles sólo por los medios y en los casos expresamente establecidos.</p>

        <p className="mb-4"><strong>Artículo 72 - El responsable.</strong> El responsable puede recurrir la sentencia absolutoria cuando le imponga una sanción pecuniaria, o solamente de las disposiciones que contenga la sentencia condenatoria sobre la restitución o cargos formulados en los casos previstos en el capítulo siguiente.</p>

        <p className="mb-4"><strong>Artículo 73 - Condiciones.</strong> Los recursos previstos en este Capítulo deben interponerse y fundarse bajo pena de inadmisibilidad, en las condiciones de tiempo y en las formas previstas en la presente.</p>

        <p className="mb-4"><strong>Artículo 74 - Efecto suspensivo.</strong> La resolución del Tribunal no es ejecutable durante el término para recurrir y mientras se tramite el recurso.</p>

        <p className="mb-4"><strong>Artículo 75 - Desistimiento mandato.</strong> Para desistir de un recurso, el representante legal debe tener mandato expreso de su representado.</p>

        <p className="mb-4"><strong>Artículo 76 - Traslado.</strong> De los recursos deducidos se da traslado a la otra parte para que fundamente su posición.</p>

        <p className="subtitle"><strong>Capítulo XIII</strong></p>
        <p className="mb-4 subtitle"><strong>DE LOS RECURSOS EN PARTICULAR</strong></p>

        <p className="mb-4"><strong>Artículo 77 - De aclaración.</strong> Dentro del término de tres (3) días de dictado el auto o sentencia que decida algún incidente o termine definitivamente la causa, el Tribunal –de oficio o a pedido de parte–, puede aclarar algún concepto dudoso u oscuro. Puede también hacerse uso del mismo para que resuelva sobre algún accesorio o secundario a la cuestión principal y que haya sido omitido inadvertidamente en la resolución. En ningún caso la aclaratoria o la rectificación de cualquier error u omisión material puede importar una modificación esencial al decisorio.</p>

        <p className="mb-4"><strong>Artículo 78 - De reposición.</strong> El recurso de reposición puede ser interpuesto contra los autos que resuelvan, sin sustanciación, un incidente o interlocutoria a fin de que el mismo Tribunal que lo dicta, lo revoque o modifique por contrario imperio. La resolución recaída es ejecutoria. Este recurso es interpuesto dentro de los tres (3) días de la notificación.</p>

        <p className="mb-4">
          <strong>Artículo 79 - De revisión.</strong> El recurso de revisión es interpuesto ante el mismo Tribunal, contra sus sentencias definitivas o interlocutorias que causen estado. Es interpuesto dentro de los diez (10) días de notificada la sentencia definitiva y fundado en:
          <br /><strong>a)</strong> Por el responsable:
          <br /><strong>1)</strong> Pruebas o documentos nuevos que hagan al descargo del responsable obligado.
          <br /><strong>2)</strong> En la no consideración o errónea interpretación de documentos ya presentados en autos. Para su interposición no es necesario el depósito previo del cargo formulado.
          <br /><strong>b)</strong> Por la Fiscalía de Investigaciones Administrativas: Pruebas o documentos nuevos que hagan al descargo del responsable obligado o meritúen su responsabilidad. También se puede interponer contra las resoluciones interlocutorias que causen estado, dentro de los cinco (5) días de notificadas.
        </p>

        <p className="subtitle"><strong>Capítulo XIV</strong></p>
        <p className="mb-4 subtitle"><strong>LA EJECUCIÓN DE LA SENTENCIA</strong></p>

        <p className="mb-4"><strong>Artículo 80 - Notificación de la sentencia.</strong> Las sentencias condenatorias del Tribunal de Cuentas se notifican al responsable declarado, en la forma prevista en la presente, con expresa intimación de hacer efectivo el importe del cargo formulado en el término de diez (10) días.</p>

        <p className="mb-4"><strong>Artículo 81 - Cumplimiento.</strong> Si el o los responsables condenados por la sentencia dan cumplimiento a la misma, depositando su importe a la orden del Tribunal como correspondiente a la causa, los autos son archivados sin más trámite, quedando finalizado el juicio.</p>

        <p className="mb-4"><strong>Artículo 82 - Incumplimiento.</strong> Si el o los responsables no efectúan el depósito de los cargos formulados, una vez firme la sentencia, el Tribunal de Cuentas ordena expedición de testimonio de la sentencia y autos de liquidación que son enviados a la Fiscalía de Estado, quien lleva adelante el juicio de apremio con las consiguientes medidas precautorias que la ley autoriza contra los responsables declarados.</p>

        <p className="mb-4"><strong>Artículo 83 - Instrumento público.</strong> El testimonio de la sentencia condenatoria, en su parte ejecutoria y del auto de liquidación, son instrumentos públicos de conformidad al artículo 979, inciso 5) del Código Civil y por consiguiente título suficiente para la vía procesal de apremio.</p>

        <p className="subtitle"><strong>Capítulo XV</strong></p>
        <p className="mb-4 subtitle"><strong>DISPOSICIONES COMUNES</strong></p>

        <p className="mb-4"><strong>Artículo 84 - Los términos.</strong> Los plazos establecidos en la presente, lo son en días hábiles en todos los casos.</p>

        <p className="mb-4"><strong>Artículo 85 - Los intereses.</strong> Sin excepción corren intereses a cargo del o los responsables deudores y del tipo bancario en las operaciones de descuentos a particulares, desde el día siguiente al vencimiento del emplazamiento aludido en el artículo 80 de la presente.</p>

        <p className="mb-4"><strong>Artículo 86 - Períodos de inactividad.</strong> El Presidente, Vocales y colaboradores gozan anualmente de los períodos de inactividad en su función jurisdiccional, coincidente con las llamadas ferias judiciales. En tal sentido, los días inhábiles judiciales se consideran inhábiles para el Tribunal de Cuentas, respecto de cualquier término o vista.</p>

        <p className="mb-4"><strong>Artículo 87 - La habilitación.</strong> Para la atención de los asuntos cuya urgencia no admita dilación, queda a cargo de la feria un miembro de Tribunal con el personal que se determine.</p>

        <p className="subtitle"><strong>Capítulo XVI</strong></p>
        <p className="mb-4 subtitle"><strong>DE LA SINDICATURA EN LAS EMPRESAS PÚBLICAS</strong></p>

        <p className="mb-4"><strong>Artículo 88 - Disposiciones aplicables.</strong> La sindicatura de las empresas públicas está regida por las disposiciones de este capítulo y en lo que sea aplicable, por las demás normas de la presente.</p>

        <p className="mb-4"><strong>Artículo 89 - Designación. Elección.</strong> El Tribunal de Cuentas provee a la designación de los miembros de las Sindicaturas Individuales y/o Sindicaturas Colegiadas de las sociedades con participación accionaria de la provincia, cuya tenencia accionaria permita la designación de uno o varios síndicos o integrantes de Comisiones de Fiscalización u otros órganos de control interno en representación del capital estatal, en base a las propuestas del Poder Ejecutivo cuya elección, en cumplimiento del artículo 284 de la Ley Nacional Nº 19.550, es efectuada por las asambleas de accionistas de las respectivas sociedades.</p>

        <p className="mb-4"><strong>Artículo 90 - Prohibición.</strong> Los síndicos o integrantes de comisiones de fiscalización, no pueden pertenecer a la planta de personal escalafonado o superior, ni tener forma alguna de vinculación laboral con los órganos de control interno o externo establecidos en la Constitución Provincial.</p>

        <p className="mb-4"><strong>Artículo 91 - Organización interna. Auditorías.</strong> Dentro de la organización interna del Tribunal debe incluirse una dependencia a cargo de uno de los Vocales, que tiene incumbencia en el control externo de las empresas públicas. Las auditorías se realizan en forma periódica, por lo menos una vez por año, además de las que pueden realizarse en cualquier momento y sin previo aviso. Los informes de situación son tratados en plenario del Tribunal y se incluyen en el informe anual o especial según corresponda.</p>

        <p className="mb-4"><strong>Artículo 92 - Responsabilidad. Informes.</strong> Los síndicos o fiscalizadores designados son responsables por los perjuicios que sufra el Estado por el mal desempeño de su cargo o función, además de las responsabilidades que determinan las leyes específicas. Deben elevar al Tribunal, informes periódicos, por lo menos en forma trimestral, remitiendo copia a los responsables de las empresas mencionadas en el artículo 89.</p>
      </div>
    </section>
  );
}
